vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.283185*(c*t+d) );
}

float smax(float a, float b, float k){
    float h = clamp((b-a)/k+.5,0.,1.);
    return mix(a,b,h) + h * (1. - h) * k * .5;
}

vec3 RN23_2(vec2 uv){
    return palette(dot(uv,vec2(fract(iTime*.001-12.3),fract(iTime*.001-34.5)))
    ,vec3(0.8, 0.5, 0.4)
    ,vec3(0.2, 0.4, 0.2)
    ,vec3(2.0, 1.0, 1.0)
    ,vec3(0.0, 0.25, 0.25));
}

vec4 HexDist(vec2 p){

    vec2 r = vec2(1.,1.73);
    vec2 h = r*.5;

    vec2 a = mod(p,r)-h;
    vec2 b = mod(p-h,r)-h;

    vec2 gv = length(a)>length(b)?b:a;

    float c = dot(abs(gv),normalize(r));
    c = smax(c,abs(gv.x), .3);

    vec2 id = p-gv;
    float x = atan(gv.x,gv.y);
    float y = .5-c;
    return vec4(x,y,id.x,id.y);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    vec3 col = vec3(0.);

    uv*=10.;
    uv.y+=iTime*.03;

    vec4 hc = HexDist(uv+100.);

    float c = smoothstep(.03,.05,hc.y*sin(hc.z*hc.w+iTime));

    col.rgb=c*RN23_2(hc.zw).yxz;

    fragColor = vec4(col,1.0);
}
